from pathlib import Path
import json
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text())
def p(k,t):e[f'A0571-B{k:04d}']=t
p(2,'艾达灵族（Aeldari）是灵族对自身种族的称呼。他们是古老的类人种族，外貌近似精灵，天生具有灵能。古圣为赢得天堂之战，将他们创造为武器；战后，灵族帝国借助网道统治银河。如今帝国早已崩溃，灵族也成为一个日渐衰亡的种族。')
p(4,'Aeldari 艾达灵族')
p(6,'陨落之后，灵族昔日的母星群变成了恐惧之眼中的老妪世界。幸存者散落于网道与群星之间，分属许多派系：阿苏焉尼，即方舟灵族，在帝国末期逃出，栖身于小行星般庞大的方舟世界；黑暗灵族在帝国覆灭前，藏入网道中的古城科摩罗；蛮荒灵族则更早离去，迁往银河边缘绿意盎然的少女世界。另有守护隐秘黑色图书馆、传承灵族历史的丑角，追随死神的死神军，以及被统称为安赫拉特的弃民、叛离者与各路海盗。')
p(9,'外表上，灵族与人类十分相似，但通常更高、更纤细，轮廓分明，耳尖突出。依人类标准，他们极为长寿；若不死于意外或疾病，多数能活过千年。有人根据“陨落至今仅历五代”的记载，估算其平均寿命超过两千年。灵族的新陈代谢远快于人类，心血管与神经系统也更为发达，赋予他们惊人的反应与敏捷。在灵族眼中，人类行动迟缓而笨拙；人类则觉得灵族举止优雅得令人出神，战斗时更快得目不暇接。整个种族都具有很强的灵能天赋，这也构成其技术基础。主动修炼灵能的个体，寿命似乎还会随造诣增长，大先知更能活数千年。灵族心智能力远超人类，情感体验也强烈得多，因此必须不断约束自己，以免精神崩溃。')
p(16,'今日的灵族，本质上是一群流离失所的幸存者，散落着昔日文明的余威；即便处境如此艰难，他们仍是银河中的强大力量。一万年前，灵族曾是最强盛、最繁荣的种族之一，掌控银河大片区域，安享富足。其他种族虽也拥有先进技术与强大军力，却无力真正威胁灵族文明。然而，灾难最终来自内部。傲慢使他们失去自制，繁荣又让他们无须从事多少劳动，于是任何好奇与欲望都成了追逐对象。钻研奇异知识、沉迷肉欲、追求愈发出格娱乐的教派，迅速兴起。许多人继而走向禁忌学问、即时享乐与无度暴力的深渊，灵族陨落由此开始。')
p(22,'这种行为足以摧毁任何社会，对灵族而言却尤其致命。在平行的亚空间中，放纵产生的灵能波动不断汇聚，死去的信徒与追随者的灵魂，又为之增添力量。恶习日益深重，这团力量也随之膨胀，终于孕育出独立的生命与意识：色孽，吞噬灵魂、毁灭灵族的存在。祂诞生时发出的灵能尖啸，将周围一千光年内所有灵族的灵魂撕离身体。觉醒的冲击撕开了现实与亚空间之间的裂口，使灵族母星群落入虚实之间。这里便是如今的恐惧之眼，混沌势力的巢穴。据本篇记述，还有许多灵族幸存于陨落，却被困在恐惧之眼的老妪世界，沦为色孽的奴隶。')
p(24,'自这场被称为“陨落”的灾难后，灵族便分崩离析，失去共同的目标与凝聚力，人口持续减少。')
p(26,'第41千年末，大裂隙几乎将银河一分为二，灵族称其为“达瑟迪安”。他们对灵能极为敏感，因此尤其深受伴随而来的以太异象影响。灾难降临前后，灵族还经历了许多巨变，包括死神军诞生、科摩罗大析离、比耶坦破碎，以及灵能觉醒。')
p(29,'灵族极重精神信仰，文化深深扎根于一系列神话传说。其中最著名的是“天堂之战”：铸造之神瓦尔与战神血手凯恩分别率领诸神，展开史诗般的争斗。')
p(31,'按本节所采用的记述，除两位著名的例外，灵族诸神已随色孽诞生而覆灭。灵族仍敬奉诸神，在神话中保存祂们的故事，却不再期待祂们回应祈求、出手相助。不过，一则预言称，诸神终将归来，团结一致，与色孽交战并将其毁灭。这究竟只是古老传说，还是未来的预示，仍不得而知。')
p(34,'Asuryani warrior 阿苏焉尼战士')
p(36,'星镖武器——灵族的制式武器以重力驱动，向敌人射出单分子厚度的薄片。常见形式包括星镖手枪、星镖炮，以及一种名为星镖枪的轻型卡宾枪。')
p(38,'魂石——灵族死后，灵魂可能遭色孽吞噬。为避免这一命运，他们佩戴魂石，在死亡瞬间收容灵魂，再由同胞回收，嵌入方舟世界的无限回路，与先祖一同安息。危急时，最强大战士的魂石也会被取出，装入幽冥护卫、幽冥领主等灵骨机兵，再度为方舟世界而战。')
p(40,'网道——灵族很早便采用一种比直接穿行亚空间更快、更安全的航行方式。网道由穿越亚空间的古老“隧道”组成，隔绝其危险，连接现实空间中的固定门户，形成庞大而错综复杂的网络。然而，若目的地附近没有门户，或通道不足以让所需兵力通过，优势便无法发挥。如今，许多网道已被遗忘、荒废，隧道与门户遭封闭或损坏，往往迫使旅者辗转中转，才能抵达目的地。传说中的黑色图书馆就藏于网道某处，只有丑角知道它的位置。')
p(42,'灵骨——灵族最主要的建材，也是灵能技术工程的基础。吟骨者以灵能从亚空间引出灵骨，再将其塑形，建造方舟世界、坦克与其他载具、幽冥护卫和幽冥领主等机兵，以及武器护甲。灵骨能够传导灵能，既提供结构支撑，也承担供能与通信。它极其坚韧，并有一定的自我修复能力。与灵族其他建材一样，它的生长与反应更像有机组织、植物，而非其他种族使用的死物材料。')
p(45,'色孽诞生、灵族陨落之后，母星群陷入恐惧之眼，幸存者被迫离乡。灵族社会由此分化为不同文化，各自发展出独特的生活方式。每个群体内部又有许多分支，以下所列则是主要类别。')
p(47,'Graph of Aeldari Factions and Races 艾达灵族派系与族群示意图')
p(49,'灵族各群体仍共享语言与神话，只是敬奉程度各异。转换生活方式固然不易，但任何群体的成员，都有可能最终融入另一个群体。')
p(52,'方舟灵族又称阿苏焉尼，是完全以星际航行为生存方式的艾达灵族社会。')
p(57,'方舟世界的灵族经历了彻底的社会改革。每个人都会选择一条近似职业的“道途”，专心修习，直至精通，再转入另一条道途，重新开始。道途种类繁多，数量不详，却都潜藏危险：个体可能过度沉迷，从此无法离开。')
p(59,'外界最熟悉的或许是战士道途。修习者以破碎战神凯恩的某一面相为典范，成为支派战士；深陷其中、无法自拔者，则成为主教。方舟社会通常受先知道途的修习者指引，尤其是那些迷失于无数可能未来、被称为“大先知”的灵族。')
p(62,'陨落前，留在母星的灵族并非都屈从于色孽的诱惑。许多人努力挽救同胞，却始终无法改变文明的命运。最杰出的先知瞥见将至的黑暗，遂倾尽全力组织救亡。据本篇叙述，各母星都建起巨舰，由吟唱塑成灵骨，规模几乎相当于小行星。最后一批未受腐化的居民登舰，尽可能带走艺术品、植物与动物。这些巨舰后来被称为方舟世界。最后的撤离勉强赶在灾难前开始：一些方舟遭灵能冲击波摧毁，另一些被引向恐惧之眼周边的轨道，其余则漂泊于银河。彼此联系困难且时断时续，因此总数难以确认。著名者包括：')
p(64,'阿莱托克——位于银河遥远边疆、已探索空域的边缘。当地灵族抵御色孽诱惑的戒律，比其他方舟更为严苛。边疆环境与严格生活，使许多居民在某个时期选择独自或结伴离舰游历；但危难时，他们仍会归来。因此，阿莱托克军队通常拥有大量侦察兵与游侠。')
p(66,'奥坦萨——这座小型方舟曾处于陨落冲击波边缘，长期被认为已与母星群一同失陷于恐惧之眼。不过，后来有报告称曾目击它出现，甚至参与针对恐惧之眼的战役，因此其最终命运再次成为疑问。')
p(68,'比耶坦——最崇尚武力的方舟之一，立志重建灵族帝国。其精锐部队占比在各方舟中最高，战争中依靠公民民兵的程度则较低。这支训练有素的大军称为“剑风”，经常援助蛮荒灵族世界。')
p(70,'伊扬登——曾是幸存方舟中最大、最繁荣者之一，却因航线与泰伦入侵相交，险些覆灭。许多区域至今仍是废墟，人口稀少，迫使他们频繁唤醒亡者，投入远超其他方舟数量的幽冥护卫与幽冥领主，支援日渐凋零的生者军队。')
p(72,'塞姆罕——在大型方舟中，以粗犷、狂野著称。其战士偏爱迅猛突袭与机动作战，常将悬浮艇、喷气摩托编成“狂野骑士”部队，以速度与凶猛闻名。')
p(74,'乌斯维——最大的方舟之一，受恐惧之眼牵引，如今环绕其运行。这里不断面对混沌掠夺者的威胁，数千年来始终是抵御黑暗力量的堡垒。长年战争磨炼了居民，也促使他们维持一支称为“黑色守护者”的常备民兵。紧邻恐惧之眼，还使当地灵能者数量异常众多。')
p(76,'幸存灵族中，或许大多数生活在方舟世界，但实际人口无法确定。方舟保存着昔日母星仅存的遗产，是灵族工业、技术与文化的核心。多数方舟设有特殊生态穹顶，精心照料来自母星的植物与野生动物。各方舟行动、治理基本独立，却通常愿意相互援助、交换建议。分歧偶尔也会引发武装冲突，但这始终是最后的选择。')
p(78,'每座方舟世界都有无限回路，其本体便是方舟的灵骨骨架。亡者灵魂在其中以群体意识的形式存在，既为星舰提供灵能力量，也形成庞大的先祖心智，指引生者。色孽诞生后，这已是灵族最接近安宁来世的归宿；未能收容、融入其中的灵魂，将流落亚空间，被大敌吞噬。因此，灵族保卫方舟时的愤怒与坚韧，几乎无可比拟：他们可能失去的，不只是家园，还有先祖的灵魂。')
p(79,'Exodites 蛮荒灵族')
n.update({'A0571-B0002':'Aeldari采用官方艾达灵族，Eldar旧称正文按灵族自然使用。','A0571-B0006':'Asuryani沿09核心阿苏焉尼；Ynnari为死神军而非死神名字，Ynnead为因尼德。Maiden Worlds少女世界与Exodite Worlds蛮荒灵族世界相关但不自动等同。','A0571-B0009':'五代推算寿命是所给材料的估计，不能把代际长度和个体寿命当作已验证等式；保留估计语气。','A0571-B0022':'came to consciousness 为形成意识，不是意识到某项事实；tore souls from 指灵魂被撕离身体。','A0571-B0029':'此处天堂之战为灵族诸神神话，不消除其与古圣、太空死灵战争叙述的视角区别。','A0571-B0031':'两位神祇幸存为该段原始口径，与后续涉及伊莎、因尼德等内容的时期与定义可能不同，保留版本限定。','A0571-B0038':'Wraithguard采用GW09/GW10第6页幽冥护卫，原幽冥守卫为异译。','A0571-B0040':'网道安全性为原文概述；不引申为每条损毁通道绝对安全。Black Library of Chaos在此为灵族黑色图书馆，不是混沌阵营掌管的图书馆。','A0571-B0045':'坠入恐惧之眼的是母星群，非全体幸存者；原译指代错乱。','A0571-B0059':'Path of the Seer先知道途与Farseer大先知分别处理；Exarch暂沿主教，非人类宗教职衔。','A0571-B0062':'各母星分别建方舟是本篇版本叙述，保留来源限定，不覆盖其他起源资料。','A0571-B0066':'奥坦萨条目描述保留其资料时点，不把当时疑问概括为现行全设定未知。'})
for fn,obj in [('edits.json',e),('notes.json',n)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
(P/'partial_progress.json').write_text(json.dumps({'article':571,'read_through_block':244,'edited_through_block':79,'complete':False},ensure_ascii=False,indent=2))
